window.docContents[68].resolve({"/Types/#Type-Systems--Types___-Type-Systems--Typed-Arithmetic-Expressions":{"contents":"To motivate the discussion of type systems, let's begin as usual with a\ntiny toy language. We want it to have the potential for programs to go\nwrong because of runtime type errors, so we endow it with two kinds of\ndata — numbers and booleans — where not every operation is defined on\nboth types of data. For example, program terms like 5 + true and\nif 42 then 0 else 1 use undefined operator/data-type combinations.The language definition is completely routine.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Type Systems\u0009Types: Type Systems","header":"4.1. Typed Arithmetic Expressions","id":"/Types/#Type-Systems--Types___-Type-Systems--Typed-Arithmetic-Expressions"}});